	public void addToOrders( AssignOrdersToEncounterCommand command ) throws ProcessingException {
		
		
		// -------------------------------------------
		// load the parent
		// -------------------------------------------
		load( command.getEncounterId() );

		ClinicalOrderService childDelegate 	= ClinicalOrderService.getClinicalOrderInstance();
		EncounterService parentDelegate = EncounterService.getEncounterInstance();		
		UUID childId = command.getAddTo().getClinicalOrderId();
		
		try {		
			// --------------------------------------
	    	// validate the command
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );			
		}
		catch( Exception exc ) {
			final String msg = "Failed to add a ClinicalOrder as Orders to Encounter" ; 
			LOGGER.log( Level.WARNING, msg, exc );
			throw new ProcessingException( msg, exc );
		}

	}

    /**
     * remove ClinicalOrder from Orders
     * @param		command RemoveOrdersFromEncounterCommand
     * @exception	ProcessingException
     */     	
	public void removeFromOrders( RemoveOrdersFromEncounterCommand command ) throws ProcessingException {		
		
		ClinicalOrderService childDelegate 	= ClinicalOrderService.getClinicalOrderInstance();
		UUID childId = command.getRemoveFrom().getClinicalOrderId();

		try {
			
			// --------------------------------------
	    	// validate the command
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
	    	// issue the command
	    	// --------------------------------------    	
			commandGateway.sendAndWait( command );

		}
		catch( Exception exc ) {
			final String msg = "Failed to remove child using Id " + childId; 
			LOGGER.log( Level.WARNING, msg, exc );
			throw new ProcessingException( msg, exc );
		}
	}



	/**
	 * Internal helper method to load the root 
	 * 
	 * @param		id	UUID
	 * @return		Encounter
	 */
	protected Encounter load( UUID id ) throws ProcessingException {
		encounter = EncounterService.getEncounterInstance().getEncounter( new EncounterFetchOneSummary(id) );	
		return encounter;
	}


